1	<!doctype html>
2	<html lang="pt-BR">
3	<head>
4	<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
5	<title>AutoSeguro · Base de conhecimento</title>
6	<style>
7	/* Mock da tela "Base de conhecimento" — leitura do que alimenta o LLM de atendimento.
8	   Paleta, casca (.app/.lateral/.menu/.selo) e tokens copiados de index.html para manter a identidade visual.
9	   Página local, fora do git — protótipo, versão 0, somente leitura. */
10	:root{
11	  --fundo:#16012F; --superficie:#1F0A40; --superficie-2:#2A1152; --borda:#3B2068;
12	  --texto:#F2ECFF; --texto-fraco:#B9A8D9; --texto-mais-fraco:#8B79B0;
13	  --magenta:#FF00FF; --ciano:#00FFFF; --azul:#198BF5;
14	  --ok:#3DDC97; --alerta:#FFC857; --falha:#FF5C7A;
15	  --r:14px; --mono:ui-monospace,"Cascadia Mono",Consolas,monospace;
16	  --lateral:248px;
17	}
18	*{box-sizing:border-box}
19	[hidden]{display:none!important}
20	html,body{height:100%}
21	body{margin:0;background:var(--fundo);color:var(--texto);
22	     font:15px/1.5 system-ui,"Segoe UI",Roboto,sans-serif;
23	     background-image:radial-gradient(900px 500px at 15% -10%, rgba(255,0,255,.10), transparent 60%),
24	                      radial-gradient(800px 500px at 92% 0%, rgba(0,255,255,.07), transparent 55%);
25	     background-attachment:fixed}
26	a{color:var(--ciano)}
27	button{font:inherit;color:inherit}
28	:focus-visible{outline:2px solid var(--ciano);outline-offset:2px}
29	
30	/* ───── casca (igual ao index.html) ───── */
31	.app{display:grid;grid-template-columns:var(--lateral) 1fr;min-height:100vh}
32	@media (max-width:860px){ .app{grid-template-columns:1fr} .lateral{display:none} }
33	.lateral{background:rgba(22,1,47,.72);border-right:1px solid var(--borda);padding:18px 14px;
34	         display:flex;flex-direction:column;gap:18px;backdrop-filter:blur(6px)}
35	.produto{display:flex;flex-direction:column;gap:3px;padding:4px 8px 0}
36	.produto b{font-size:19px;position:relative;display:inline-block;isolation:isolate}
37	.produto b::before,.produto b::after{content:attr(data-t);position:absolute;inset:0;z-index:-1}
38	.produto b::before{color:var(--magenta);transform:translate(-2px,1px)}
39	.produto b::after{color:var(--ciano);transform:translate(2px,-1px)}
40	.produto span{color:var(--texto-mais-fraco);font-size:11.5px}
41	.menu{display:flex;flex-direction:column;gap:3px}
42	.menu .grupo{color:var(--texto-mais-fraco);font-size:10.5px;text-transform:uppercase;letter-spacing:.12em;padding:12px 10px 5px}
43	.menu a{display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:10px;color:var(--texto-fraco);
44	        text-decoration:none;font-size:14px;border:1px solid transparent}
45	.menu a:hover{background:var(--superficie);color:var(--texto)}
46	.menu a[aria-current="page"]{background:var(--superficie-2);color:var(--texto);border-color:var(--borda);box-shadow:inset 2px 0 0 var(--magenta)}
47	.menu a .ic{width:18px;text-align:center}
48	.selo{margin-top:auto;background:rgba(255,255,255,.04);border:1px solid var(--borda);border-radius:12px;padding:9px 10px}
49	.selo small{color:var(--texto-mais-fraco);font-size:10.5px;line-height:1.3;display:block}
50	
51	/* ───── área principal ───── */
52	.principal{display:flex;flex-direction:column;min-width:0}
53	.barra{display:flex;align-items:center;gap:10px;padding:16px 20px;border-bottom:1px solid var(--borda);flex-wrap:wrap}
54	.barra h1{font-size:20px;margin:0;font-weight:650}
55	.selo-mock{font-family:var(--mono);font-size:10.5px;color:var(--alerta);border:1px dashed rgba(255,200,87,.5);
56	           border-radius:999px;padding:1px 9px;white-space:nowrap}
57	.palco{flex:1}
58	.coluna{max-width:980px;margin:0 auto;padding:22px 20px 60px}
59	.subtitulo{color:var(--texto-fraco);margin:0 0 24px;max-width:78ch;font-size:14.5px}
60	
61	/* ───── abas ───── */
62	.abas{display:flex;gap:6px;flex-wrap:wrap;border-bottom:1px solid var(--borda);margin-bottom:20px}
63	.aba{background:transparent;border:1px solid transparent;border-bottom:none;padding:9px 13px;border-radius:10px 10px 0 0;
64	     color:var(--texto-fraco);cursor:pointer;font:inherit;font-size:13.5px;display:flex;gap:7px;align-items:center}
65	.aba:hover{color:var(--texto)}
66	.aba .n{background:var(--superficie-2);color:var(--texto-mais-fraco);border-radius:999px;padding:1px 8px;font-size:11px;font-family:var(--mono)}
67	.aba[aria-selected="true"]{background:var(--superficie);color:var(--texto);border-color:var(--borda);box-shadow:inset 0 2px 0 var(--magenta)}
68	.aba[aria-selected="true"] .n{background:var(--magenta);color:#16012F}
69	
70	.painel{display:flex;flex-direction:column;gap:16px}
71	.painel[hidden]{display:none}
72	.painel > p.explica{margin:0;color:var(--texto-fraco);font-size:13.5px;max-width:78ch}
73	
74	h2.subgrupo{font-size:11.5px;text-transform:uppercase;letter-spacing:.1em;color:var(--texto-mais-fraco);margin:6px 0 -4px}
75	
76	/* ───── itens / cards ───── */
77	.item{background:var(--superficie);border:1px solid var(--borda);border-radius:14px;padding:14px 16px}
78	.item h3{margin:0 0 6px;font-size:15px;line-height:1.35}
79	.item p{margin:4px 0}
80	.origem{font-family:var(--mono);font-size:11px;color:var(--texto-mais-fraco);margin-top:10px;padding-top:9px;border-top:1px dashed var(--borda)}
81	.origem b{color:var(--texto-fraco);font-weight:600;font-family:inherit}
82	
83	.lista-proibicoes{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
84	.lista-proibicoes li{background:var(--superficie);border:1px solid var(--borda);border-left:3px solid var(--falha);
85	                      border-radius:0 14px 14px 0;padding:11px 15px}
86	.lista-proibicoes b.n{font-family:var(--mono);color:var(--falha);margin-right:6px}
87	
88	.grade-gatilhos{display:flex;flex-wrap:wrap;gap:8px}
89	.gatilho{border-radius:999px;padding:5px 13px;font-size:12.5px;border:1px solid var(--borda);color:var(--texto-fraco);background:var(--superficie)}
90	.gatilho.ativo{border-color:rgba(61,220,151,.5);color:var(--ok)}
91	.gatilho.previsto{border-color:rgba(255,200,87,.45);color:var(--alerta)}
92	
93	.grade{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}
94	
95	.marcador{font-family:var(--mono);color:var(--ciano);background:rgba(0,255,255,.08);border-radius:6px;padding:1px 6px;font-size:12.5px}
96	.resolvido{font-size:12.5px;color:var(--texto-fraco)}
97	.resolvido b{color:var(--texto);font-variant-numeric:tabular-nums}
98	.setinha{color:var(--texto-mais-fraco);margin:0 4px}
99	
100	.pills{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0}
101	.pill{border-radius:999px;padding:2px 10px;font-size:11.5px;border:1px solid var(--borda);color:var(--texto-fraco)}
102	
103	.rotulo{display:inline-flex;align-items:center;gap:6px;font-family:var(--mono);font-size:10.5px;text-transform:uppercase;
104	        letter-spacing:.06em;border-radius:999px;padding:2px 10px;margin-bottom:8px}
105	.rotulo.usar{color:var(--ok);border:1px solid rgba(61,220,151,.5)}
106	.rotulo.anti{color:var(--falha);border:1px solid rgba(255,92,122,.5)}
107	
108	.campo{margin:8px 0}
109	.campo dt{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--texto-mais-fraco);margin:0 0 2px}
110	.campo dd{margin:0;font-size:13.5px}
111	.campo dd.mono{font-family:var(--mono);font-size:12.5px;color:var(--texto-fraco)}
112	
113	table.planos{width:100%;border-collapse:collapse;font-size:13.5px;background:var(--superficie);border:1px solid var(--borda);border-radius:14px;overflow:hidden}
114	table.planos th,table.planos td{padding:10px 14px;border-bottom:1px solid var(--borda);text-align:left;vertical-align:top}
115	table.planos thead th{color:var(--texto-mais-fraco);font-weight:600;font-size:11px;text-transform:uppercase;letter-spacing:.07em;background:rgba(255,255,255,.03)}
116	table.planos tbody tr:last-child td{border-bottom:0}
117	table.planos td.num{font-variant-numeric:tabular-nums;white-space:nowrap}
118	.nota-tabela{font-size:12.5px;color:var(--texto-mais-fraco);margin:10px 0 0}
119	
120	.status{font-family:var(--mono);font-size:10.5px;color:var(--alerta);border:1px dashed rgba(255,200,87,.5);border-radius:999px;padding:1px 9px;white-space:nowrap}
121	.item.lacuna{border-left:3px solid var(--alerta);display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}
122	
123	@media (prefers-reduced-motion:reduce){ *{animation:none!important;transition:none!important;scroll-behavior:auto!important} }
124	</style>
125	</head>
126	<body>
127	<div class="app">
128	
129	<aside class="lateral">
130	  <div class="produto"><b data-t="AutoSeguro">AutoSeguro</b><span>agente de cotação · console</span></div>
131	  <nav class="menu">
132	    <div class="grupo">Atendimento</div>
133	    <a href="index.html"><span class="ic">💬</span> Conversas</a>
134	    <a href="#"><span class="ic">🙋</span> Fila humana</a>
135	    <div class="grupo">Observabilidade</div>
136	    <a href="#"><span class="ic">🧭</span> Rastreio</a>
137	    <a href="#"><span class="ic">📈</span> Cotações</a>
138	    <a href="#"><span class="ic">🎯</span> Avaliação</a>
139	    <div class="grupo">Configuração</div>
140	    <a href="#"><span class="ic">⚖️</span> Regras e política</a>
141	    <div class="grupo">Insumos</div>
142	    <a href="historico.html"><span class="ic">📚</span> Histórico de conversas</a>
143	    <a href="conhecimento.html" aria-current="page"><span class="ic">🧠</span> Base de conhecimento</a>
144	  </nav>
145	  <div class="selo"><small>desafio técnico FDE<br>mock da tela Conversas v2</small></div>
146	</aside>
147	
148	<div class="principal">
149	  <div class="barra">
150	    <h1>Base de conhecimento</h1>
151	    <span class="selo-mock">PROTÓTIPO · versão 0 · somente leitura · edição fora do escopo</span>
152	  </div>
153	
154	  <main class="palco">
155	    <div class="coluna">
156	      <p class="subtitulo">O que o LLM de atendimento pode consultar para responder ao lead depois da cotação.
157	        Números nunca moram aqui: vêm da /planos e da /quote.</p>
158	
159	      <div class="abas" role="tablist" aria-label="Seções da base de conhecimento">
160	        <button class="aba" role="tab" data-alvo="politica" aria-selected="true">📜 Política <span class="n">17</span></button>
161	        <button class="aba" role="tab" data-alvo="glossario" aria-selected="false">📖 Glossário <span class="n">10</span></button>
162	        <button class="aba" role="tab" data-alvo="objecoes" aria-selected="false">💬 Objeções <span class="n">6</span></button>
163	        <button class="aba" role="tab" data-alvo="estilo" aria-selected="false">🗣️ Estilo <span class="n">8</span></button>
164	        <button class="aba" role="tab" data-alvo="planos" aria-selected="false">📋 Planos oficiais <span class="n">3</span></button>
165	        <button class="aba" role="tab" data-alvo="lacunas" aria-selected="false">🕳️ Lacunas <span class="n">4</span></button>
166	      </div>
167	
168	      <!-- 1. POLÍTICA -->
169	      <section class="painel" id="politica" role="tabpanel">
170	        <h2 class="subgrupo">Proibições — 7</h2>
171	        <ol class="lista-proibicoes">
172	          <li>
173	            <b class="n">1.</b>Dar preço que não venha da cotação oficial (/quote).
174	            <div class="origem"><b>origem:</b> DESIGN-PROPOSTA-v1.md §5.1 — "preço não se escreve, se prova": <code>PrecoCotado</code> só é construído a partir de uma resposta 200 da /quote.</div>
175	          </li>
176	          <li>
177	            <b class="n">2.</b>Oferecer desconto ou "rever" o preço.
178	            <div class="origem"><b>origem:</b> antiexemplo <code>generate_dataset.py:136</code></div>
179	          </li>
180	          <li>
181	            <b class="n">3.</b>Prometer ajuste de franquia para baixar a parcela.
182	            <div class="origem"><b>origem:</b> antiexemplo <code>generate_dataset.py:140</code>; <code>plans.json</code> não tem essa regra.</div>
183	          </li>
184	          <li>
185	            <b class="n">4.</b>Citar cobertura que o plano não tem.
186	            <div class="origem"><b>origem:</b> antiexemplo <code>generate_dataset.py:127</code></div>
187	          </li>
188	          <li>
189	            <b class="n">5.</b>Prometer boleto, apólice ou fechamento: isso é do corretor.
190	            <div class="origem"><b>origem:</b> DESIGN-PROPOSTA-v1.md §5.4; antiexemplo <code>generate_dataset.py:132</code></div>
191	          </li>
192	          <li>
193	            <b class="n">6.</b>Pedir CPF.
194	            <div class="origem"><b>origem:</b> DESIGN-PROPOSTA-v1.md §5.5; a /quote não usa CPF.</div>
195	          </li>
196	          <li>
197	            <b class="n">7.</b>Escrever qualquer número fora de marcador (<span class="marcador">{{...}}</span>).
198	            <div class="origem"><b>origem:</b> arquitetura aprovada, issue #41.</div>
199	          </li>
200	        </ol>
201	
202	        <h2 class="subgrupo">Gatilhos de Fila humana — 10</h2>
203	        <div class="item">
204	          <p style="margin:0 0 8px;color:var(--texto-fraco);font-size:13px">Já no protótipo (mock de <code>index.html</code>) — 4</p>
205	          <div class="grade-gatilhos">
206	            <span class="gatilho ativo">lead_quer_contratar</span>
207	            <span class="gatilho ativo">lead_pediu_humano</span>
208	            <span class="gatilho ativo">quote_indisponivel</span>
209	            <span class="gatilho ativo">recusa_regra_de_aceitacao</span>
210	          </div>
211	          <p style="margin:14px 0 8px;color:var(--texto-fraco);font-size:13px">Previstos na proposta de design §5.4 — 6</p>
212	          <div class="grade-gatilhos">
213	            <span class="gatilho previsto">pedido de desconto ou negociação</span>
214	            <span class="gatilho previsto">mídia sem transcrição</span>
215	            <span class="gatilho previsto">menção a sinistro ou urgência</span>
216	            <span class="gatilho previsto">dado impossível ou inconsistente</span>
217	            <span class="gatilho previsto">assunto fora de escopo</span>
218	            <span class="gatilho previsto">frustração ou repetição do lead</span>
219	          </div>
220	          <div class="origem"><b>origem:</b> ativos — <code>_local/mock-cotacao/index.html</code> (função <code>handoff</code>); previstos — <code>docs/DESIGN-PROPOSTA-v1.md</code> §5.4</div>
221	        </div>
222	      </section>
223	
224	      <!-- 2. GLOSSÁRIO -->
225	      <section class="painel" id="glossario" role="tabpanel" hidden>
226	        <p class="explica">Texto sem números. Os marcadores aparecem com o valor resolvido ao lado, lido de <code>plans.json</code>.</p>
227	
228	        <div class="item">
229	          <h3>Franquia</h3>
230	          <p>Franquia é o valor que você paga do seu bolso quando usa o seguro para consertar o carro depois de um dano parcial, como uma batida. O seguro paga o restante do conserto. Quanto menor a franquia, menos você paga quando precisa usar o seguro.</p>
231	          <p class="resolvido"><span class="marcador">{{franquia}}</span><span class="setinha">→</span>
232	            Essencial <b>R$ 4.500,00</b> · Completo <b>R$ 3.000,00</b> · Premium <b>R$ 1.500,00</b></p>
233	          <div class="origem"><b>origem:</b> texto — especificação do dono; valores — <code>plans.json → planos[].franquia</code></div>
234	        </div>
235	
236	        <div class="item">
237	          <h3>Carência</h3>
238	          <p>Roubo e furto só passam a valer <span class="marcador">{{carencia_dias}}</span> dias depois do início do seguro.</p>
239	          <p class="resolvido"><span class="marcador">{{carencia_dias}}</span><span class="setinha">→</span> <b>30</b> dias</p>
240	          <div class="origem"><b>origem:</b> <code>plans.json → regras.carencia</code> (<code>dias</code>)</div>
241	        </div>
242	
243	        <div class="item">
244	          <h3>Primeira parcela proporcional</h3>
245	          <p>Se o seguro começa no meio do mês, a primeira parcela cobra só os dias que faltam até o fim do mês. As seguintes são integrais.</p>
246	          <div class="origem"><b>origem:</b> <code>plans.json → regras.entrada_meio_mes</code></div>
247	        </div>
248	
249	        <h2 class="subgrupo">Coberturas — 7</h2>
250	        <div class="grade">
251	          <div class="item">
252	            <h3>Colisão <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">colisao</span></h3>
253	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
254	            <div class="pills"><span class="pill">Essencial</span><span class="pill">Completo</span><span class="pill">Premium</span></div>
255	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
256	          </div>
257	          <div class="item">
258	            <h3>Roubo <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">roubo</span></h3>
259	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
260	            <div class="pills"><span class="pill">Essencial</span><span class="pill">Completo</span><span class="pill">Premium</span></div>
261	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
262	          </div>
263	          <div class="item">
264	            <h3>Furto <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">furto</span></h3>
265	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
266	            <div class="pills"><span class="pill">Essencial</span><span class="pill">Completo</span><span class="pill">Premium</span></div>
267	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
268	          </div>
269	          <div class="item">
270	            <h3>Terceiros <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">terceiros</span></h3>
271	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
272	            <div class="pills"><span class="pill">Completo</span><span class="pill">Premium</span></div>
273	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
274	          </div>
275	          <div class="item">
276	            <h3>Vidros <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">vidros</span></h3>
277	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
278	            <div class="pills"><span class="pill">Completo</span><span class="pill">Premium</span></div>
279	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
280	          </div>
281	          <div class="item">
282	            <h3>Carro reserva <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">carro_reserva</span></h3>
283	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
284	            <div class="pills"><span class="pill">Premium</span></div>
285	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
286	          </div>
287	          <div class="item">
288	            <h3>Assistência 24h <span style="font-family:var(--mono);color:var(--texto-mais-fraco);font-size:11px">assistencia_24h</span></h3>
289	            <p style="color:var(--texto-fraco);font-size:13px">— sem descrição oficial (ver Lacunas)</p>
290	            <div class="pills"><span class="pill">Premium</span></div>
291	            <div class="origem"><b>origem:</b> <code>plans.json → planos[].coberturas</code></div>
292	          </div>
293	        </div>
294	      </section>
295	
296	      <!-- 3. OBJEÇÕES -->
297	      <section class="painel" id="objecoes" role="tabpanel" hidden>
298	        <p class="explica">O que o lead diz no histórico → como responder. Estratégias são rascunho para revisão do dono, nunca regra publicada.</p>
299	        <div class="grade">
300	
301	          <div class="item">
302	            <dl class="campo"><dt>gatilho</dt><dd>"o preco ta salgado"</dd></dl>
303	            <dl class="campo"><dt>estratégia (rascunho para revisão do dono)</dt><dd>Acolher e explicar o que o plano cobre, mostrando a diferença entre os planos pelas coberturas. Não baixar preço.</dd></dl>
304	            <dl class="campo"><dt>fatos oficiais permitidos</dt><dd class="mono"><span class="marcador">{{preco_mensal}}</span> da cotação atual · <code>planos[].coberturas</code></dd></dl>
305	            <dl class="campo"><dt>proibido</dt><dd>2 (oferecer desconto), 7 (número fora de marcador)</dd></dl>
306	            <div class="origem"><b>origem:</b> <code>generate_dataset.py:38</code> (OBJECOES)</div>
307	          </div>
308	
309	          <div class="item">
310	            <dl class="campo"><dt>gatilho</dt><dd>"a franquia ta alta"</dd></dl>
311	            <dl class="campo"><dt>estratégia (rascunho para revisão do dono)</dt><dd>Explicar o que é franquia e mostrar que planos com mais cobertura têm franquia menor.</dd></dl>
312	            <dl class="campo"><dt>fatos oficiais permitidos</dt><dd class="mono"><span class="marcador">{{franquia}}</span> → Essencial <b>R$ 4.500,00</b> · Completo <b>R$ 3.000,00</b> · Premium <b>R$ 1.500,00</b></dd></dl>
313	            <dl class="campo"><dt>proibido</dt><dd>3 (prometer ajuste de franquia), 7 (número fora de marcador)</dd></dl>
314	            <div class="origem"><b>origem:</b> <code>generate_dataset.py:38</code>; valores de franquia — <code>plans.json → planos[].franquia</code></div>
315	          </div>
316	
317	          <div class="item">
318	            <dl class="campo"><dt>gatilho</dt><dd>"vi mais barato na concorrente"</dd></dl>
319	            <dl class="campo"><dt>estratégia (rascunho para revisão do dono)</dt><dd>Não comparar preços nem citar a concorrente. Acolher e destacar coberturas e carência oficiais.</dd></dl>
320	            <dl class="campo"><dt>fatos oficiais permitidos</dt><dd class="mono"><code>planos[].coberturas</code> · carência (<span class="marcador">{{carencia_dias}}</span> → 30 dias)</dd></dl>
321	            <dl class="campo"><dt>proibido</dt><dd>1 (preço fora da /quote — inclui preço de concorrente), 7 (número fora de marcador)</dd></dl>
322	            <div class="origem"><b>origem:</b> gatilho — <code>generate_dataset.py:39</code> (OBJECOES); concorrentes citados no histórico — <code>generate_dataset.py:40</code> (CONCORRENTES)</div>
323	          </div>
324	
325	          <div class="item">
326	            <dl class="campo"><dt>gatilho</dt><dd>"preciso pensar"</dd></dl>
327	            <dl class="campo"><dt>estratégia (rascunho para revisão do dono)</dt><dd>Respeitar a decisão, resumir a cotação com marcadores e oferecer o corretor pelo WhatsApp.</dd></dl>
328	            <dl class="campo"><dt>fatos oficiais permitidos</dt><dd class="mono"><span class="marcador">{{plano}}</span> · <span class="marcador">{{preco_mensal}}</span> · <span class="marcador">{{franquia}}</span></dd></dl>
329	            <dl class="campo"><dt>proibido</dt><dd>7 (número fora de marcador)</dd></dl>
330	            <div class="origem"><b>origem:</b> <code>generate_dataset.py:39</code> (OBJECOES)</div>
331	          </div>
332	
333	          <div class="item">
334	            <dl class="campo"><dt>gatilho</dt><dd>"vou ver com minha esposa"</dd></dl>
335	            <dl class="campo"><dt>estratégia (rascunho para revisão do dono)</dt><dd>Respeitar a decisão, resumir a cotação com marcadores e oferecer o corretor pelo WhatsApp.</dd></dl>
336	            <dl class="campo"><dt>fatos oficiais permitidos</dt><dd class="mono"><span class="marcador">{{plano}}</span> · <span class="marcador">{{preco_mensal}}</span> · <span class="marcador">{{franquia}}</span></dd></dl>
337	            <dl class="campo"><dt>proibido</dt><dd>7 (número fora de marcador)</dd></dl>
338	            <div class="origem"><b>origem:</b> <code>generate_dataset.py:39</code> (OBJECOES)</div>
339	          </div>
340	
341	          <div class="item">
342	            <dl class="campo"><dt>gatilho</dt><dd>"achei caro pra esse carro"</dd></dl>
343	            <dl class="campo"><dt>estratégia (rascunho para revisão do dono)</dt><dd>Acolher e explicar o que o plano cobre, mostrando a diferença entre os planos pelas coberturas. Não baixar preço.</dd></dl>
344	            <dl class="campo"><dt>fatos oficiais permitidos</dt><dd class="mono"><span class="marcador">{{preco_mensal}}</span> da cotação atual · <code>planos[].coberturas</code></dd></dl>
345	            <dl class="campo"><dt>proibido</dt><dd>2 (oferecer desconto), 7 (número fora de marcador)</dd></dl>
346	            <div class="origem"><b>origem:</b> <code>generate_dataset.py:39</code> (OBJECOES)</div>
347	          </div>
348	
349	        </div>
350	      </section>
351	
352	      <!-- 4. ESTILO -->
353	      <section class="painel" id="estilo" role="tabpanel" hidden>
354	        <p class="explica">Tom dos vendedores do histórico: o jeito de falar, nunca os números nem as regras. Dígitos trocados por <code>#</code>, <code>{nome}</code> por <code>[NOME]</code>, <code>{plano}</code> por <code>[PLANO]</code>.</p>
355	        <div class="grade">
356	
357	          <div class="item">
358	            <span class="rotulo usar">usar tom</span>
359	            <dl class="campo"><dt>original</dt><dd class="mono">"Ola [NOME], tudo otimo! Claro, vou te ajudar. Qual o modelo e ano do veiculo?"</dd></dl>
360	            <dl class="campo"><dt>motivo</dt><dd>Saudação cordial e pergunta objetiva (modelo e ano), sem números nem promessas.</dd></dl>
361	            <dl class="campo"><dt>versão aproveitável</dt><dd>"Olá [NOME]! Vou te ajudar a cotar. Qual o modelo e o ano do seu carro?"</dd></dl>
362	            <div class="origem"><b>origem:</b> <code>generate_dataset.py:106</code></div>
363	          </div>
364	
365	          <div class="item">
