.item.lacuna{border-left:3px solid var(--alerta);display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}

/* ───── objeções de preço — fichas editáveis (protótipo, LEI do dono: quem escreve é ele) ───── */
.obj-aviso{background:rgba(255,200,87,.08);border:1px dashed rgba(255,200,87,.5);color:var(--alerta);border-radius:10px;padding:9px 13px;font-size:12.5px}
.obj-fichas{display:flex;flex-direction:column;gap:18px}
.obj-ficha .obj-rotulo{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--texto-mais-fraco);margin:14px 0 3px}
.obj-ficha .obj-rotulo:first-child{margin-top:0}
.obj-input-nome{width:100%;background:var(--superficie);border:1px solid var(--borda);border-radius:10px;color:var(--texto);padding:8px 12px;font:inherit;font-size:15px;font-weight:600}
.obj-tags{display:flex;flex-wrap:wrap;gap:6px;margin:2px 0 8px}
.obj-tag{display:inline-flex;align-items:center;gap:6px;background:var(--superficie-2);border:1px solid var(--borda);border-radius:999px;padding:3px 6px 3px 12px;font-size:12.5px;color:var(--texto)}
.obj-tag small{color:var(--texto-mais-fraco);font-size:10px;font-family:var(--mono)}
.obj-tag-remove{background:transparent;border:none;color:var(--texto-mais-fraco);cursor:pointer;font-size:14px;line-height:1;padding:2px 6px;border-radius:999px}
.obj-tag-remove:hover{color:var(--falha);background:rgba(255,92,122,.12)}
.obj-input-frase{width:100%;background:var(--superficie);border:1px solid var(--borda);border-radius:10px;color:var(--texto);padding:7px 11px;font:inherit;font-size:13px}
.obj-textarea{width:100%;min-height:92px;resize:vertical;background:var(--superficie);border:1px solid var(--borda);border-radius:10px;color:var(--texto);padding:10px 12px;font:inherit;font-size:13.5px;line-height:1.5}
.obj-marcadores{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.obj-marcador-btn{display:inline-flex;align-items:center;gap:6px;background:rgba(0,255,255,.06);border:1px solid rgba(0,255,255,.35);color:var(--ciano);border-radius:999px;padding:3px 10px;font-family:var(--mono);font-size:12px;cursor:pointer}
.obj-marcador-btn:hover{background:rgba(0,255,255,.14)}
.obj-marcador-btn small{color:var(--texto-fraco);font-family:system-ui,sans-serif}
.obj-erro{color:var(--falha);font-size:12.5px;margin:6px 0 0;display:flex;flex-direction:column;gap:2px}
.obj-args{display:flex;flex-direction:column;gap:6px;margin:2px 0}
.obj-arg-item{display:flex;align-items:center;gap:8px;font-size:13.5px;color:var(--texto-fraco);cursor:pointer}
.obj-arg-item input{accent-color:var(--magenta)}
.obj-tentativas{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.obj-tentativas-input{width:64px;background:var(--superficie);border:1px solid var(--borda);border-radius:8px;color:var(--texto);padding:6px 9px;font:inherit}
.obj-legenda{color:var(--texto-mais-fraco);font-size:12px;margin:6px 0 0}
.obj-previa{background:rgba(255,255,255,.03);border:1px dashed var(--borda);border-radius:10px;padding:10px 12px;font-size:13.5px;white-space:pre-wrap;min-height:1.6em}
.obj-previa-legenda{color:var(--texto-mais-fraco);font-size:11.5px;margin:4px 0 0}
.obj-status{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-top:12px;margin-top:6px;border-top:1px dashed var(--borda)}
.obj-selo{font-family:var(--mono);font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;border-radius:999px;padding:3px 11px}
.obj-selo.rascunho{color:var(--alerta);border:1px solid rgba(255,200,87,.5)}
.obj-selo.publicado{color:var(--ok);border:1px solid rgba(61,220,151,.5)}
.obj-botao{background:var(--superficie-2);border:1px solid var(--borda);color:var(--texto);border-radius:999px;padding:7px 15px;font-size:13px;cursor:pointer}
.obj-botao:hover{border-color:var(--ciano)}
.obj-botao.primario{background:rgba(255,0,255,.12);border-color:rgba(255,0,255,.5)}
.obj-botao.primario:hover{border-color:var(--magenta)}
.obj-botao:disabled{opacity:.4;cursor:not-allowed}
.obj-botao:disabled:hover{border-color:var(--borda)}
