<script>
/* Objeções de preço — fichas editáveis (protótipo).
   Regra do dono: quem escreve a resposta é ele; a IA nunca pré-preenche texto/estratégia.
   Persistência em localStorage, todo acesso protegido por try/catch (página funciona sem storage). */
(function(){

  function lsGet(chave){
    try{
      var bruto = localStorage.getItem(chave);
      return bruto ? JSON.parse(bruto) : null;
    }catch(e){ return null; }
  }
  function lsSet(chave, valor){
    try{
      localStorage.setItem(chave, JSON.stringify(valor));
      return true;
    }catch(e){ return false; }
  }

  function formatBRL(n){
    var partes = Number(n).toFixed(2).split(".");
    var inteiro = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    return "R$ " + inteiro + "," + partes[1];
  }

  function formatDataHora(d){
    function pad(n){ return String(n).padStart(2, "0"); }
    return pad(d.getDate()) + "/" + pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
  }

  function inserirNoCursor(textarea, texto){
    var start = typeof textarea.selectionStart === "number" ? textarea.selectionStart : textarea.value.length;
    var end = typeof textarea.selectionEnd === "number" ? textarea.selectionEnd : start;
    var valor = textarea.value;
    textarea.value = valor.slice(0, start) + texto + valor.slice(end);
    var pos = start + texto.length;
    textarea.focus();
    try{ textarea.setSelectionRange(pos, pos); }catch(e){}
  }

  // franquias — plans.json → planos[].franquia
  var FRANQUIAS = { essencial: 4500, completo: 3000, premium: 1500 };
  // carência — plans.json → regras.carencia.dias
  var CARENCIA_DIAS = 30;

  // valores de exemplo: cotação real da /quote para Completo, 35 anos, carro 2019, CEP [REDIGIDO]
  var MARCADORES = [
    { id: "plano", exemplo: "Completo" },
    { id: "preco_mensal", exemplo: "R$ 241,38" },
    { id: "franquia", exemplo: formatBRL(FRANQUIAS.completo) },
    { id: "franquia_essencial", exemplo: formatBRL(FRANQUIAS.essencial) },
    { id: "franquia_completo", exemplo: formatBRL(FRANQUIAS.completo) },
    { id: "franquia_premium", exemplo: formatBRL(FRANQUIAS.premium) },
    { id: "carencia_dias", exemplo: String(CARENCIA_DIAS) },
    { id: "coberturas", exemplo: "Colisão, Roubo, Furto, Terceiros, Vidros" }
  ];
  var MARCADORES_POR_ID = {};
  MARCADORES.forEach(function(m){ MARCADORES_POR_ID[m.id] = m; });

  var ARGUMENTOS = [
    { id: "coberturas", label: "Coberturas do plano" },
    { id: "franquia", label: "Franquia de cada plano" },
    { id: "carencia", label: "Carência" },
    { id: "comparacao", label: "Comparação entre planos" }
  ];

  // gatilhos — scripts/generate_dataset.py:38-39 (OBJECOES); nomes sugeridos pelo dono no pedido desta ficha
  var OBJECOES = [
    { id: "preco-salgado", nomeSugerido: "Preço salgado", fraseOriginal: "o preco ta salgado", origemFrase: "generate_dataset.py:38 (OBJECOES)" },
    { id: "franquia-alta", nomeSugerido: "Franquia alta", fraseOriginal: "a franquia ta alta", origemFrase: "generate_dataset.py:38 (OBJECOES)" },
    { id: "concorrente-barato", nomeSugerido: "Concorrente mais barato", fraseOriginal: "vi mais barato na concorrente", origemFrase: "generate_dataset.py:39 (OBJECOES)" },
    { id: "caro-pro-carro", nomeSugerido: "Caro para esse carro", fraseOriginal: "achei caro pra esse carro", origemFrase: "generate_dataset.py:39 (OBJECOES)" }
  ];

  function estadoPadrao(cfg){
    var base = {
      nome: cfg.nomeSugerido,
      frases: [{ texto: cfg.fraseOriginal, origem: "historico" }],
      resposta: "",
      argumentos: {},
      tentativas: "",
      publicado: false,
      versao: 0,
      salvoEm: null
    };
    ARGUMENTOS.forEach(function(a){ base.argumentos[a.id] = false; });
    return base;
  }

  function carregarEstado(cfg, chave){
    var base = estadoPadrao(cfg);
    var salvo;
    try{ salvo = lsGet(chave); }catch(e){ salvo = null; }
    if(!salvo || typeof salvo !== "object"){ return base; }
    try{
      var estado = estadoPadrao(cfg);
      if(typeof salvo.nome === "string" && salvo.nome.trim()) estado.nome = salvo.nome;
      if(Array.isArray(salvo.frases) && salvo.frases.length){
        var temHistorico = salvo.frases.some(function(f){ return f && f.origem === "historico"; });
        estado.frases = temHistorico ? salvo.frases : base.frases.concat(salvo.frases);
      }
      if(typeof salvo.resposta === "string") estado.resposta = salvo.resposta;
      if(salvo.argumentos && typeof salvo.argumentos === "object"){
        ARGUMENTOS.forEach(function(a){ estado.argumentos[a.id] = !!salvo.argumentos[a.id]; });
      }
      if(typeof salvo.tentativas === "string" || typeof salvo.tentativas === "number") estado.tentativas = String(salvo.tentativas);
      estado.publicado = !!salvo.publicado;
      estado.versao = typeof salvo.versao === "number" ? salvo.versao : 0;
      estado.salvoEm = typeof salvo.salvoEm === "string" ? salvo.salvoEm : null;
      return estado;
    }catch(e){ return base; }
  }

  function analisarResposta(texto){
    var desconhecidos = [];
    var vistos = {};
    var semMarcadores = texto.replace(/\{\{\s*([^}]*)\s*\}\}/g, function(_, nome){
      var chave = (nome || "").trim();
      if(!MARCADORES_POR_ID[chave] && !vistos[chave]){
        vistos[chave] = true;
        desconhecidos.push(chave);
      }
      return "";
    });
    return { digitoForaDeMarcador: /\d/.test(semMarcadores), desconhecidos: desconhecidos };
  }

  function montarPrevia(texto){
    return texto.replace(/\{\{\s*([^}]*)\s*\}\}/g, function(m, nome){
      var chave = (nome || "").trim();
      var marcador = MARCADORES_POR_ID[chave];
      return marcador ? marcador.exemplo : m;
    });
  }

  function criarFichaEl(){
    var el = document.createElement("div");
    el.className = "item obj-ficha";
    el.innerHTML =
      '<div class="obj-rotulo">Objeção</div>' +
      '<input type="text" class="obj-input-nome" data-f="nome">' +
      '<div class="obj-rotulo">Frases do lead</div>' +
      '<div class="obj-tags" data-f="tags"></div>' +
      '<input type="text" class="obj-input-frase" data-f="add-frase" placeholder="Acrescentar frase do lead… (Enter para adicionar)">' +
      '<div class="obj-rotulo">Como a IA deve responder</div>' +
      '<textarea class="obj-textarea" data-f="resposta" placeholder="Escreva como a IA deve responder a esta objeção. Números só como marcadores, ex.: {{franquia}}."></textarea>' +
      '<div class="obj-erro" data-f="erros" hidden></div>' +
      '<div class="obj-rotulo">Marcadores disponíveis</div>' +
      '<div class="obj-marcadores" data-f="marcadores"></div>' +
      '<div class="obj-rotulo">Argumentos que a IA pode usar</div>' +
      '<div class="obj-args" data-f="args"></div>' +
      '<div class="obj-rotulo">Quantas vezes a IA argumenta antes de passar para um corretor</div>' +
      '<div class="obj-tentativas"><input type="number" min="1" max="5" class="obj-tentativas-input" data-f="tentativas"></div>' +
      '<p class="obj-legenda">Depois disso, a IA oferece um corretor e o lead entra na Fila humana.</p>' +
      '<div class="obj-rotulo">Prévia para o lead</div>' +
      '<div class="obj-previa" data-f="previa">—</div>' +
      '<p class="obj-previa-legenda">Prévia com valores de exemplo; no sistema, os valores vêm da cotação real.</p>' +
      '<div class="obj-status" data-f="status">' +
        '<span class="obj-selo" data-f="selo"></span>' +
        '<button type="button" class="obj-botao" data-f="btn-salvar">Salvar rascunho</button>' +
        '<button type="button" class="obj-botao primario" data-f="btn-publicar">Publicar</button>' +
        '<ul class="obj-faltando" data-f="faltando" hidden></ul>' +
        '<p class="obj-versao" data-f="versao" hidden></p>' +
      "</div>" +
      '<div class="origem" data-f="origem"></div>';
    return el;
  }

  function initFicha(cfg, container){
    var chave = "conhecimento.objecao." + cfg.id;
    var state = carregarEstado(cfg, chave);

    var el = criarFichaEl();
    container.appendChild(el);

    var elNome = el.querySelector('[data-f="nome"]');
    var elTags = el.querySelector('[data-f="tags"]');
    var elAddFrase = el.querySelector('[data-f="add-frase"]');
    var elResposta = el.querySelector('[data-f="resposta"]');
    var elErros = el.querySelector('[data-f="erros"]');
    var elMarcadores = el.querySelector('[data-f="marcadores"]');
    var elArgs = el.querySelector('[data-f="args"]');
    var elTentativas = el.querySelector('[data-f="tentativas"]');
    var elPrevia = el.querySelector('[data-f="previa"]');
    var elSelo = el.querySelector('[data-f="selo"]');
    var elBtnSalvar = el.querySelector('[data-f="btn-salvar"]');
    var elBtnPublicar = el.querySelector('[data-f="btn-publicar"]');
    var elFaltando = el.querySelector('[data-f="faltando"]');
    var elVersao = el.querySelector('[data-f="versao"]');
    var elOrigem = el.querySelector('[data-f="origem"]');
    elOrigem.innerHTML = "<b>origem:</b> <code>" + cfg.origemFrase + "</code>";

    MARCADORES.forEach(function(m){
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "obj-marcador-btn";
      var codeSpan = document.createElement("span");
      codeSpan.textContent = "{{" + m.id + "}}";
      var exSmall = document.createElement("small");
      exSmall.textContent = "→ " + m.exemplo;
      btn.appendChild(codeSpan);
      btn.appendChild(exSmall);
      btn.addEventListener("click", function(){
        inserirNoCursor(elResposta, "{{" + m.id + "}}");
        state.resposta = elResposta.value;
        marcarEditado();
        atualizarTudo();
      });
      elMarcadores.appendChild(btn);
    });

    ARGUMENTOS.forEach(function(a){
      var label = document.createElement("label");
      label.className = "obj-arg-item";
      var cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = !!state.argumentos[a.id];
      cb.addEventListener("change", function(){
        state.argumentos[a.id] = cb.checked;
        marcarEditado();
        atualizarTudo();
      });
      var span = document.createElement("span");
      span.textContent = a.label;
      label.appendChild(cb);
      label.appendChild(span);
      elArgs.appendChild(label);
    });

    function renderTags(){
      elTags.innerHTML = "";
      state.frases.forEach(function(f, i){
        var tag = document.createElement("span");
        tag.className = "obj-tag";
        var txt = document.createElement("span");
        txt.textContent = '"' + f.texto + '"';
        tag.appendChild(txt);
        if(f.origem === "historico"){
          var sm = document.createElement("small");
          sm.textContent = "origem: histórico";
          tag.appendChild(sm);
        } else {
          var rm = document.createElement("button");
          rm.type = "button";
          rm.className = "obj-tag-remove";
          rm.setAttribute("aria-label", "Remover frase");
          rm.textContent = "×";
          rm.addEventListener("click", function(){
            state.frases.splice(i, 1);
            marcarEditado();
            renderTags();
            atualizarTudo();
          });
          tag.appendChild(rm);
        }
        elTags.appendChild(tag);
      });
    }

    function marcarEditado(){
      if(state.publicado){ state.publicado = false; }
    }

    function atualizarTudo(){
      var texto = state.resposta || "";
      var analise = analisarResposta(texto);

      var linhasErro = [];
      if(analise.digitoForaDeMarcador){
        linhasErro.push("Há número fora de marcador. Use um marcador — números só vêm da tabela oficial.");
      }
      analise.desconhecidos.forEach(function(d){
        linhasErro.push("Marcador desconhecido: {{" + d + "}}");
      });
      elErros.innerHTML = "";
      if(linhasErro.length){
        linhasErro.forEach(function(l){
          var p = document.createElement("div");
          p.textContent = l;
          elErros.appendChild(p);
        });
        elErros.hidden = false;
      } else {
        elErros.hidden = true;
      }

      elPrevia.textContent = texto.trim() ? montarPrevia(texto) : "—";

      var faltando = [];
      if(!texto.trim()) faltando.push("Escreva a resposta.");
      if(analise.digitoForaDeMarcador) faltando.push("Há número fora de marcador.");
      analise.desconhecidos.forEach(function(d){ faltando.push("Marcador desconhecido: {{" + d + "}}."); });
      var algumArgumento = ARGUMENTOS.some(function(a){ return !!state.argumentos[a.id]; });
      if(!algumArgumento) faltando.push("Marque pelo menos 1 argumento.");
      var tentNum = parseInt(state.tentativas, 10);
      if(state.tentativas === "" || isNaN(tentNum) || tentNum < 1 || tentNum > 5){
        faltando.push("Preencha as tentativas entre 1 e 5.");
      }

      elBtnPublicar.disabled = faltando.length > 0;
      elFaltando.innerHTML = "";
      if(faltando.length){
        faltando.forEach(function(f){
          var li = document.createElement("li");
          li.textContent = f;
          elFaltando.appendChild(li);
        });
        elFaltando.hidden = false;
      } else {
        elFaltando.hidden = true;
      }

      if(state.publicado){
        elSelo.textContent = "Publicado";
        elSelo.className = "obj-selo publicado";
      } else if(state.versao > 0){
        elSelo.textContent = "Rascunho (alterações não publicadas)";
        elSelo.className = "obj-selo rascunho";
      } else {
        elSelo.textContent = "Rascunho";
        elSelo.className = "obj-selo rascunho";
      }

      if(state.salvoEm){
        elVersao.textContent = "versão " + state.versao + " · salvo em " + state.salvoEm;
        elVersao.hidden = false;
      } else {
        elVersao.hidden = true;
      }
    }

    elNome.value = state.nome;
    elResposta.value = state.resposta;
    elTentativas.value = state.tentativas;
    renderTags();

    elNome.addEventListener("input", function(){
      state.nome = elNome.value;
      marcarEditado();
      atualizarTudo();
    });
    elAddFrase.addEventListener("keydown", function(e){
      if(e.key === "Enter"){
        e.preventDefault();
        var v = elAddFrase.value.trim();
        if(v){
          state.frases.push({ texto: v, origem: "acrescentada" });
          elAddFrase.value = "";
          marcarEditado();
          renderTags();
          atualizarTudo();
        }
      }
    });
    elResposta.addEventListener("input", function(){
      state.resposta = elResposta.value;
      marcarEditado();
      atualizarTudo();
    });
    elTentativas.addEventListener("input", function(){
      state.tentativas = elTentativas.value;
      marcarEditado();
      atualizarTudo();
    });
    elBtnSalvar.addEventListener("click", function(){
      state.salvoEm = formatDataHora(new Date());
      lsSet(chave, state);
      atualizarTudo();
    });
    elBtnPublicar.addEventListener("click", function(){
      var analise = analisarResposta(state.resposta || "");
      var algumArgumento = ARGUMENTOS.some(function(a){ return !!state.argumentos[a.id]; });
      var tentNum = parseInt(state.tentativas, 10);
      var ok = (state.resposta || "").trim() && !analise.digitoForaDeMarcador && !analise.desconhecidos.length &&
        algumArgumento && !isNaN(tentNum) && tentNum >= 1 && tentNum <= 5;
      if(!ok) return;
      state.publicado = true;
      state.versao = (state.versao || 0) + 1;
      state.salvoEm = formatDataHora(new Date());
      lsSet(chave, state);
      atualizarTudo();
    });

    atualizarTudo();
  }

  var container = document.getElementById("objecoes-precos");
  if(container){
    OBJECOES.forEach(function(cfg){ initFicha(cfg, container); });
  }
})();
</script>
</body>
